files.patch:
Index: workspace/deliverable/q4_pl_adjusted.json
===================================================================
--- workspace/deliverable/q4_pl_adjusted.json
+++ workspace/deliverable/q4_pl_adjusted.json
@@ -13,7 +13,7 @@
   },
   "going_concern": {
     "substantial_doubt": true,
     "plans_probable": false,
-    "disclosure": "Disclose in the 2025 financial statements that substantial doubt about the entity's ability to continue as a going concern exists (ASC 205-40-50-1 to 50-14). Conditions: 13-week cash flow forecast shows cash turning negative in week 8 (ending 2026-02-20, -105,000) and reaching -509,000 by 2026-03-27 absent new financing. Plans considered: Crestline $3.0M convertible note term sheet is non-binding and subject to conditions precedent (Q4 revenue >= 1,500,000 - which fails at corrected revenue of 850,000 - and no going-concern qualification); per the library a non-binding term sheet with conditions precedent is not a probable plan, so the doubt is not alleviated and the substantial-doubt disclosure is required."
+    "disclosure": "Disclose in the 2025 financial statements that substantial doubt about the entity's ability to continue as a going concern exists (ASC 205-40-50-1 to 50-14). Conditions: 13-week cash flow forecast shows cash turning negative in week 8 (ending 2026-02-20, -105,000) and reaching -509,000 by 2026-03-27 absent new financing. Plans considered: Crestline $3.0M convertible note term sheet is non-binding and subject to conditions precedent (Q4 revenue >= 1,500,000 - which fails at corrected revenue of 850,000 - and no going-concern qualification); per the library a non-binding term sheet with conditions precedent is not a probable plan, so the doubt is not alleviated and the substantial-doubt disclosure is required. Client confirmed (Turn 2) there is no forecast beyond 13 weeks, no other financing plan, and no signed/waived Crestline commitment; the evaluation window beyond 2026-03-27 is an explicitly flagged documentation gap that does not alleviate the doubt."
   }
 }

input.command:
cd /work && python3 -c "
import json; d=json.load(open('workspace/deliverable/q4_pl_adjusted.json'))
assert d['revenue_as_drafted']+sum(d['adjustments'].values())==d['revenue_corrected']==850000
assert d['going_concern']=={'substantial_doubt':True,'plans_probable':False,'disclosure':d['going_concern']['disclosure']}
print('JSON valid; revenue 850,000; hosting keys', list(d['hosting']), '; rou/liab', d['hosting']['rou_asset'], d['hosting']['lease_liability'])
" && ls /work/workspace/deliverable/

